from pathlib import Path
import re

html_path=Path('despesas-reembolsos-v2.html')
js_path=Path('despesas-reembolsos-v2.js')
html=html_path.read_text(encoding='utf-8')
js=js_path.read_text(encoding='utf-8')

# --- HTML / CSS ---
old_css='.catalogs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.catalog{background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px}.catalog h3{margin:0 0 10px}.catalog-item{padding:7px 0;border-bottom:1px solid #edf1f5;display:grid}.catalog-item small{color:var(--muted)}'
new_css='.catalogs{display:block}.catalog-manager{background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden}.catalog-tabs{display:flex;gap:4px;overflow:auto;padding:10px;border-bottom:1px solid var(--line);background:#f8fafd}.catalog-tab{border:0;background:transparent;padding:9px 11px;border-radius:8px;white-space:nowrap;cursor:pointer;color:#53647b;font-weight:700}.catalog-tab.active{background:var(--navy);color:#fff}.catalog-panel{padding:14px}.catalog-panel-head{display:flex;align-items:center;gap:10px;margin-bottom:12px}.catalog-panel-head h3{margin:0}.catalog-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid #edf1f5}.catalog-row:last-child{border-bottom:0}.catalog-row small{display:block;color:var(--muted);margin-top:2px}.catalog-row-actions{display:flex;gap:6px;flex-wrap:wrap}.map-link{display:inline-flex;align-items:center;gap:5px;margin-top:4px;color:var(--blue);font-size:11px;font-weight:700;text-decoration:none}.map-link:hover{text-decoration:underline}'
if old_css not in html: raise SystemExit('catalog css not found')
html=html.replace(old_css,new_css,1)

old_desc='<div class="field full"><label>Descrição *</label><input id="eDesc"></div>'
new_desc='<div class="field full"><label>Descrição / motivo da despesa *</label><input id="eDesc" placeholder="Ex.: Visita ao cliente, reunião, atendimento em campo…"><small>Preenchimento manual. O scanner não altera este campo.</small></div>'
if old_desc not in html: raise SystemExit('description field not found')
html=html.replace(old_desc,new_desc,1)

old_vendor='<div class="field"><label>Fornecedor / estabelecimento</label><input id="eVendor"></div><div class="field"><label>CNPJ / CPF</label><input id="eVendorDoc" inputmode="numeric" maxlength="18"></div><div class="field full"><label>Endereço</label><input id="eAddress"></div>'
new_vendor='<div class="field"><label>Fornecedor / estabelecimento</label><input id="eVendor"></div><div class="field"><label>CNPJ / CPF do estabelecimento</label><input id="eVendorDoc" inputmode="numeric" maxlength="18"></div><div class="field full"><label>Endereço do estabelecimento</label><input id="eAddress"><a id="eAddressMap" class="map-link hidden" target="_blank" rel="noopener">Abrir endereço no mapa</a></div><div class="field full"><label>Itens / consumo identificados na nota</label><textarea id="eItems" placeholder="Preenchido automaticamente quando a nota informar os produtos ou serviços"></textarea><small>Este campo vem da nota. A descrição/motivo da despesa acima continua manual.</small></div><div class="field"><label>Consumidor da nota (CPF/CNPJ)</label><input id="eConsumerDoc" inputmode="numeric" maxlength="18" placeholder="Quando informado na NFC-e"></div>'
if old_vendor not in html: raise SystemExit('vendor/address fields not found')
html=html.replace(old_vendor,new_vendor,1)

old_geo='<span id="geoText" class="chip hidden"></span>'
new_geo='<a id="geoText" class="chip hidden" target="_blank" rel="noopener"></a>'
if old_geo not in html: raise SystemExit('geo text not found')
html=html.replace(old_geo,new_geo,1)

html=re.sub(r'\.\/despesas-reembolsos-v2\.js\?v=\d+', './despesas-reembolsos-v2.js?v=10', html)

# --- JS constants and globals ---
js=js.replace("const FISCAL_API='https://kvfjjtkwxxbvzlicwnrz.supabase.co/functions/v1/fiscal-qr-api';", "const FISCAL_API='https://kvfjjtkwxxbvzlicwnrz.supabase.co/functions/v1/fiscal-smart-api';\nconst CATALOG_API='https://kvfjjtkwxxbvzlicwnrz.supabase.co/functions/v1/expense-catalog-api';",1)
js=js.replace("const api=(p,o)=>call(EXP_API,p,o),scheduleApi=(p,o)=>call(SCHEDULE_API,p,o),cardApi=(p,o)=>call(CARD_API,p,o),fiscalApi=(p,o)=>call(FISCAL_API,p,o),finalizeApi=(p,o)=>call(FINALIZE_API,p,o);", "const api=(p,o)=>call(EXP_API,p,o),scheduleApi=(p,o)=>call(SCHEDULE_API,p,o),cardApi=(p,o)=>call(CARD_API,p,o),fiscalApi=(p,o)=>call(FISCAL_API,p,o),finalizeApi=(p,o)=>call(FINALIZE_API,p,o),catalogApi=(p,o)=>call(CATALOG_API,p,o);",1)
js=js.replace("let token='',B=null,events=[],expenses=[],reimbursements=[],agenda=[],cards=[],geo=null,fiscal={},qrScanner=null,sortKey='incurred_at',sortDir=-1;", "let token='',B=null,events=[],expenses=[],reimbursements=[],agenda=[],cards=[],geo=null,fiscal={},qrScanner=null,sortKey='incurred_at',sortDir=-1,catalogTab='category';",1)

# Preload QR library after app boot so opening the scanner is immediate.
js=js.replace("$('loading').classList.add('hidden');$('app').classList.remove('hidden')", "$('loading').classList.add('hidden');$('app').classList.remove('hidden');loadQrScanner().catch(()=>{})",1)

# Map and validation helpers.
anchor='function updateSubmitMode()'
helpers=r'''function validFiscalVendor(v){const s=String(v||'').trim();return Boolean(s)&&!/(?:DATA\s*\/?\s*HORA|DATA\s+DE\s+EMISS|EMISS[AÃ]O|AUTORIZA[CÇ][AÃ]O|PROTOCOLO|INFORMA[CÇ][ÕO]ES?\s+DE\s+INTERESSE|CONTRIBUINTE|DOCUMENTO\s+AUXILIAR|CONSULTA|CHAVE\s+DE\s+ACESSO|^\d{2}[\/.-]\d{2}[\/.-]\d{4})/i.test(s)}
function mapUrlAddress(v){const s=String(v||'').trim();return s?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(s):''}
function mapUrlGeo(lat,lng){return Number.isFinite(Number(lat))&&Number.isFinite(Number(lng))?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(`${lat},${lng}`):''}
function updateMapLinks(){const a=$('eAddressMap'),u=mapUrlAddress($('eAddress')?.value);if(a){a.href=u||'#';a.classList.toggle('hidden',!u)}}
function renderGeoLink(){const a=$('geoText');if(!a)return;if(!geo){a.classList.add('hidden');a.removeAttribute('href');a.textContent='';return}a.href=mapUrlGeo(geo.latitude,geo.longitude);a.textContent=`${Number(geo.latitude).toFixed(5)}, ${Number(geo.longitude).toFixed(5)} · Abrir no mapa`;a.classList.remove('hidden')}
'''
if anchor not in js: raise SystemExit('updateSubmitMode anchor not found')
js=js.replace(anchor,helpers+anchor,1)

# Main fiscal-to-form mapping: never touch description; populate items and consumer.
pattern=r"function applyFiscalToExpense\(d\)\{.*?\}\nfunction fillFiscal"
replacement=r'''function applyFiscalToExpense(d){const cat=inferredCategory(d),vendor=[d.trade_name,d.legal_name,d.establishment].find(validFiscalVendor);if(vendor)$('eVendor').value=vendor;if(d.cnpj)$('eVendorDoc').value=formatDocument(d.cnpj);if(d.address)$('eAddress').value=d.address;if(Array.isArray(d.items)&&d.items.length)$('eItems').value=d.items.join('\n');if(d.consumer_document)$('eConsumerDoc').value=formatDocument(d.consumer_document);if(d.value!=null&&Number(d.value)>0)$('eAmount').value=Number(d.value);if(d.date_time){const x=String(d.date_time).match(/(\d{2})[\/.-](\d{2})[\/.-](\d{4})(?:\s+(\d{2}:\d{2}))?/);if(x)$('eDate').value=`${x[3]}-${x[2]}-${x[1]}T${x[4]||'12:00'}`}if(cat)setCategoryByName(cat);if(d.payment_method){const p=B.paymentMethods.find(x=>String(d.payment_method).toLowerCase().includes('pix')?/pix/i.test(x.name):/cr[eé]dito/i.test(d.payment_method)?/cr[eé]dito/i.test(x.name):/d[eé]bito/i.test(d.payment_method)?/d[eé]bito/i.test(x.name):/dinheiro/i.test(d.payment_method)?/dinheiro/i.test(x.name):false);if(p){$('ePayment').value=p.payment_method_id;paymentChanged()}}renderInstallmentPreview();maskTarget($('eVendorDoc'));maskTarget($('eConsumerDoc'));updateMapLinks();return cat}
function fillFiscal'''
js,n=re.subn(pattern,lambda m: replacement,js,count=1,flags=re.S)
if n!=1: raise SystemExit(f'applyFiscalToExpense replacement={n}')

# Replace fillFiscal so technical and visible fields stay aligned.
pattern=r"function fillFiscal\(raw,sync=true\)\{.*?\}\nasync function loadQrScanner"
replacement=r'''function fillFiscal(raw,sync=true){const d=sanitizeFiscalResult(raw);d.items=Array.isArray(raw?.items)?raw.items.filter(Boolean):[];d.category_hint=raw?.category_hint||d.category_hint||'';d.legal_name=raw?.legal_name||d.legal_name||'';d.trade_name=raw?.trade_name||d.trade_name||'';d.cnae=raw?.cnae||d.cnae||'';d.cnae_description=raw?.cnae_description||d.cnae_description||'';d.consumer_document=digits(raw?.consumer_document||d.consumer_document||'').slice(0,14);fiscal={...fiscal,...d};$('fiscalBox').classList.remove('hidden');$('fVendor').value=[d.trade_name,d.legal_name,d.establishment].find(validFiscalVendor)||'';$('fCnpj').value=formatDocument(d.cnpj||'');$('fAddress').value=d.address||'';$('fNumber').value=d.number||'';$('fSeries').value=d.series||'';if($('fItems'))$('fItems').value=d.items.join('\n');$('fKey').value=formatAccessKey(d.access_key||'');$('fDate').value=d.date_time||'';$('fValue').value=d.value??'';$('fPayment').value=d.payment_method||'';$('fQr').value=d.official_query_url||'';if($('eItems')&&d.items.length)$('eItems').value=d.items.join('\n');if($('eConsumerDoc')&&d.consumer_document)$('eConsumerDoc').value=formatDocument(d.consumer_document);const cat=sync?applyFiscalToExpense(d):inferredCategory(d);const vendor=[d.trade_name,d.legal_name,d.establishment].find(validFiscalVendor),bits=[d.number?'NF '+d.number:'',cat||'',vendor||''].filter(Boolean);$('fiscalTechnicalSummary').textContent=(bits.length?bits.join(' · '):'Nota fiscal reconhecida')+' · Ver dados da nota';updateMapLinks()}
async function loadQrScanner'''
js,n=re.subn(pattern,lambda m: replacement,js,count=1,flags=re.S)
if n!=1: raise SystemExit(f'fillFiscal replacement={n}')

# Faster scanner: QR-only, preloaded, more frames and a larger detection area.
pattern=r"async function startQrScan\(\)\{.*?\}\nasync function loadTesseract"
replacement=r'''async function startQrScan(){try{await loadQrScanner();$('qrModal').classList.remove('hidden');$('scanStatus').textContent='Aponte para o QR Code…';const cfg=window.Html5QrcodeSupportedFormats?{formatsToSupport:[Html5QrcodeSupportedFormats.QR_CODE],verbose:false}:{verbose:false};qrScanner=new Html5Qrcode('qrReader',cfg);let done=false;await qrScanner.start({facingMode:'environment'},{fps:20,qrbox:(w,h)=>{const s=Math.floor(Math.min(w,h)*.88);return{width:s,height:s}},disableFlip:true,aspectRatio:1.7777778},text=>{if(done)return;done=true;const raw=String(text||'').trim(),local=localFiscalFromQr(raw);fillFiscal(local,true);$('scanStatus').textContent='QR reconhecido. Buscando dados da nota…';$('qrModal').classList.add('hidden');const scanner=qrScanner;qrScanner=null;setTimeout(async()=>{try{if(scanner){await scanner.stop().catch(()=>{});await scanner.clear().catch(()=>{})}}catch(e){console.warn('Encerramento do scanner',e)}},0);setTimeout(()=>resolveFiscalQr(raw,local),0)},()=>{})}catch(e){console.error(e);await stopQrScan();$('scanStatus').textContent='Não foi possível abrir o leitor de QR: '+e.message}}
async function loadTesseract'''
js,n=re.subn(pattern,lambda m: replacement,js,count=1,flags=re.S)
if n!=1: raise SystemExit(f'startQrScan replacement={n}')

# OCR local extraction for consumer/items too.
anchor='async function scanFiscal(file)'
ocr_helpers=r'''function localConsumerFromText(text,issuer=''){const flat=String(text||'').replace(/\s+/g,' '),p=[/(?:CONSUMIDOR|DESTINAT[AÁ]RIO)[\s\S]{0,160}?(?:CPF|CNPJ)\s*[:\-]?\s*([0-9.\/\-]{11,20})/i,/(?:CPF|CNPJ)\s+(?:DO\s+)?(?:CONSUMIDOR|DESTINAT[AÁ]RIO)\s*[:\-]?\s*([0-9.\/\-]{11,20})/i];for(const r of p){const m=flat.match(r),d=digits(m?.[1]||'');if((d.length===11||d.length===14)&&d!==digits(issuer))return d}return''}
function localItemsFromText(text){const lines=String(text||'').split(/\r?\n/).map(x=>x.replace(/\s+/g,' ').trim()).filter(Boolean),out=[];for(let i=0;i<lines.length;i++){const line=lines[i],near=[lines[i-1],lines[i+1],lines[i+2]].filter(Boolean).join(' ');if(line.length<3||line.length>120||!/\p{L}/u.test(line)||/CNPJ|CPF|CONSUMIDOR|CHAVE|PROTOCOLO|TOTAL|TRIBUT|ENDERE[CÇ]O|DOCUMENTO|NFC|NF-E/i.test(line))continue;if(/QTD|QTDE|QUANTIDADE|VL\.?\s*UNIT|VALOR\s*UNIT|LITRO|\bLT\b|\bKG\b|UNIDADE|X\s*R\$/i.test(near)&&!out.includes(line))out.push(line)}return out.slice(0,20)}
'''
if anchor not in js: raise SystemExit('scanFiscal anchor not found')
js=js.replace(anchor,ocr_helpers+anchor,1)

old_scan_tail="const parsed=parseFiscalText(text,qr);parsed.qr_used=qrUsed;parsed.ocr_used=ocrUsed;fillFiscal(parsed,true);"
new_scan_tail="const parsed=parseFiscalText(text,qr);parsed.qr_used=qrUsed;parsed.ocr_used=ocrUsed;parsed.consumer_document=localConsumerFromText(text,parsed.cnpj);parsed.items=localItemsFromText(text);parsed.category_hint=inferredCategory({...parsed,ocr_text:text});fillFiscal(parsed,true);"
if old_scan_tail not in js: raise SystemExit('scanFiscal tail not found')
js=js.replace(old_scan_tail,new_scan_tail,1)

# Store visible consumer/items in fiscal JSON.
pattern=r"function collectFiscal\(\)\{return\{.*?\}\}"
replacement="function collectFiscal(){return{establishment:$('fVendor').value||$('eVendor').value||null,cnpj:digits($('fCnpj').value||$('eVendorDoc').value)||null,address:$('fAddress').value||$('eAddress').value||null,number:digits($('fNumber').value)||null,series:digits($('fSeries').value)||null,access_key:digits($('fKey').value)||null,date_time:$('fDate').value||null,value:$('fValue').value?Number($('fValue').value):null,payment_method:$('fPayment').value||null,official_query_url:$('fQr').value||null,items:String($('eItems')?.value||'').split(/\\r?\\n/).map(x=>x.trim()).filter(Boolean),consumer_document:digits($('eConsumerDoc')?.value)||null,category_hint:fiscal.category_hint||null,legal_name:fiscal.legal_name||null,trade_name:fiscal.trade_name||null,cnae:fiscal.cnae||null,cnae_description:fiscal.cnae_description||null,ocr_used:Boolean(fiscal.ocr_used),qr_used:Boolean(fiscal.qr_used)}}"
js,n=re.subn(pattern,lambda m: replacement,js,count=1,flags=re.S)
if n!=1: raise SystemExit(f'collectFiscal replacement={n}')

# CPF/CNPJ mask also on consumer.
js=js.replace("if(el.id==='fCnpj'||el.id==='eVendorDoc'||/\\b(cpf|cnpj)\\b/.test(sig))", "if(el.id==='fCnpj'||el.id==='eVendorDoc'||el.id==='eConsumerDoc'||/\\b(cpf|cnpj)\\b/.test(sig))",1)

# Draft restores map links and geolocation link.
js=js.replace("if(d.fiscal_data)fillFiscal(d.fiscal_data,false);toggleEvent();installmentChanged()", "if(d.fiscal_data)fillFiscal(d.fiscal_data,false);toggleEvent();installmentChanged();updateMapLinks();renderGeoLink()",1)
js=js.replace("function clearForm(){localStorage.removeItem(DRAFT_KEY);$('expenseForm').reset();fiscal={};geo=null;", "function clearForm(){localStorage.removeItem(DRAFT_KEY);$('expenseForm').reset();fiscal={};geo=null;renderGeoLink();",1)

# Saved expense detail with clickable maps, consumer and consumed items.
pattern=r"function openExpense\(x\)\{.*?\}\nfunction reviewForm"
replacement=r'''function openExpense(x){$('modalTitle').textContent='Despesa';const parts=agenda.filter(a=>a.expense_id===x.expense_id),fd=x.fiscal_data||{},addr=x.vendor_address||fd.address||'',items=Array.isArray(fd.items)?fd.items:[],consumer=fd.consumer_document||'',vendor=x.vendor_name||fd.trade_name||fd.legal_name||fd.establishment||'',addressLink=addr?`<a class="map-link" target="_blank" rel="noopener" href="${esc(mapUrlAddress(addr))}">${esc(addr)} · Abrir no mapa</a>`:'—',geoLink=x.latitude!=null&&x.longitude!=null?`<a class="map-link" target="_blank" rel="noopener" href="${esc(mapUrlGeo(x.latitude,x.longitude))}">${Number(x.latitude).toFixed(5)}, ${Number(x.longitude).toFixed(5)} · Abrir no mapa</a>`:'';$('modalBody').innerHTML=`<div class="detail"><h3>${esc(x.description)}</h3><p>${badge(x.status)} · ${esc(company(x.company_key))} · ${esc(user(x.paid_by_user_id))}</p><p><b>Fornecedor:</b> ${esc(vendor||'—')}${x.vendor_document?` · <b>CNPJ/CPF:</b> ${esc(formatDocument(x.vendor_document))}`:''}</p><p><b>Endereço:</b> ${addressLink}</p>${consumer?`<p><b>Consumidor da nota:</b> ${esc(formatDocument(consumer))}</p>`:''}${items.length?`<p><b>Itens / consumo da nota:</b><br>${items.map(esc).join('<br>')}</p>`:''}${geoLink?`<p><b>Localização registrada:</b> ${geoLink}</p>`:''}<p><b>Solicitado:</b> ${money(x.requested_amount)} · <b>Aprovado:</b> ${x.approved_amount==null?'—':money(x.approved_amount)} · <b>Reembolsado:</b> ${money(x.reimbursed_amount)} · <b>Pendente:</b> ${money(x.pending_amount)}</p><p><b>Reembolsável:</b> ${x.reimbursable?'Sim':'Não'}${x.card_id?' · <b>Cartão:</b> '+esc(cardLabel(by(cards,x.card_id,'card_id')||{nickname:'Cartão',last4:'????',card_type:'PESSOAL'})):''}</p>${parts.length?`<h4>Parcelas</h4>${parts.map(p=>`<div>${p.installment_number}/${p.installment_count} · ${new Date(p.due_date+'T12:00:00').toLocaleDateString('pt-BR')} · ${money(p.scheduled_amount)} · ${badge(p.status)}</div>`).join('')}`:''}${x.adjustment_reason?`<p><b>Ajuste:</b> ${esc(x.adjustment_reason)}</p>`:''}${x.rejection_reason?`<p><b>Recusa:</b> ${esc(x.rejection_reason)}</p>`:''}<div class="actions">${(x.attachments||[]).map(a=>a.url?`<a class="btn" target="_blank" rel="noopener" href="${esc(a.url)}">${esc(a.original_name||a.attachment_type)}</a>`:'').join('')}</div></div>`;const canFinish=(x.status==='RASCUNHO'||x.status==='AJUSTE_SOLICITADO')&&(B.user.administrator||x.paid_by_user_id===B.user.id);$('modalActions').innerHTML='<button class="btn" id="modalClose">Fechar</button>'+(canFinish?`<button class="btn primary" id="sendExpense">${x.reimbursable?'Enviar para aprovação':'Registrar despesa'}</button>`:'')+(B.permissions.approve&&x.reimbursable&&['ENVIADA_PARA_APROVACAO','EM_ANALISE'].includes(x.status)?'<button class="btn good" id="approveExpense">Aprovar</button><button class="btn warn" id="adjustExpense">Solicitar ajuste</button><button class="btn bad" id="rejectExpense">Recusar</button>':'');showModal();$('modalClose').onclick=hideModal;if($('sendExpense'))$('sendExpense').onclick=async()=>{if(x.reimbursable)await api('/review',{method:'POST',body:JSON.stringify({expense_id:x.expense_id,action:'ENVIAR',request_id:crypto.randomUUID()})});else await finalizeApi('/finalize',{method:'POST',body:JSON.stringify({expense_id:x.expense_id,request_id:crypto.randomUUID()})});hideModal();await reload()};if($('approveExpense'))$('approveExpense').onclick=()=>reviewForm(x,'APROVAR');if($('adjustExpense'))$('adjustExpense').onclick=()=>reviewForm(x,'SOLICITAR_AJUSTE');if($('rejectExpense'))$('rejectExpense').onclick=()=>reviewForm(x,'RECUSAR')}
function reviewForm'''
js,n=re.subn(pattern,lambda m: replacement,js,count=1,flags=re.S)
if n!=1: raise SystemExit(f'openExpense replacement={n}')

# --- Catalogs: tabbed CRUD UI ---
pattern=r"function renderCatalogs\(\)\{.*?\}\nasync function loadAudit"
replacement=r'''function catalogDefs(){return[{label:'Categorias',type:'category',rows:B.categories,id:'category_id'},{label:'Centros de custo',type:'cost_center',rows:B.costCenters,id:'cost_center_id'},{label:'Projetos',type:'project',rows:B.projects,id:'project_id'},{label:'Formas de pagamento',type:'payment_method',rows:B.paymentMethods,id:'payment_method_id'}]}
function renderCatalogs(){const defs=catalogDefs(),valid=[...defs.map(x=>x.type),'cards'];if(!valid.includes(catalogTab))catalogTab='category';const tabs=defs.map(d=>`<button class="catalog-tab ${catalogTab===d.type?'active':''}" data-cat-tab="${d.type}">${d.label}</button>`).join('')+`<button class="catalog-tab ${catalogTab==='cards'?'active':''}" data-cat-tab="cards">Cartões</button>`;let panel='';if(catalogTab==='cards'){const visible=cards.filter(c=>c.card_type==='PESSOAL'||!currentCompany()||c.company_key===currentCompany());panel=`<div class="catalog-panel"><div class="catalog-panel-head"><div class="grow"><h3>Cartões</h3><small>Cartões cadastrados para identificar uma compra quando necessário.</small></div><button class="btn" id="addPersonalCard">+ Pessoal</button>${B.permissions.admin?'<button class="btn primary" id="addCompanyCard">+ Empresa</button>':''}</div>${visible.map(c=>`<div class="catalog-row"><div><b>${esc(c.nickname)} · •••• ${esc(c.last4)}</b><small>${c.card_type==='EMPRESA'?esc(company(c.company_key))+' · corporativo':esc(c.owner_name||'Pessoal')}${c.brand?' · '+esc(c.brand):''}${c.issuer?' · '+esc(c.issuer):''}</small></div><div class="catalog-row-actions"><button class="btn" data-card-edit="${c.card_id}">Editar</button><button class="btn bad" data-card-del="${c.card_id}">Excluir</button></div></div>`).join('')||'<div class="empty">Nenhum cartão cadastrado.</div>'}</div>`}else{const d=defs.find(x=>x.type===catalogTab),rows=d.rows.filter(x=>!currentCompany()||x.company_key===currentCompany());panel=`<div class="catalog-panel"><div class="catalog-panel-head"><div class="grow"><h3>${d.label}</h3><small>${rows.length} cadastro(s) ativo(s)</small></div><button class="btn primary" data-add="${d.type}">+ Adicionar</button></div>${rows.map(x=>`<div class="catalog-row"><div><b>${esc(x.name)}</b><small>${esc(company(x.company_key))}${x.code?' · '+esc(x.code):''}${x.description?' · '+esc(x.description):''}</small></div><div class="catalog-row-actions"><button class="btn" data-cat-edit="${d.type}" data-id="${x[d.id]}">Editar</button><button class="btn bad" data-cat-del="${d.type}" data-id="${x[d.id]}">Excluir</button></div></div>`).join('')||'<div class="empty">Nenhum cadastro nesta seção.</div>'}</div>`}$('catalogGrid').innerHTML=`<div class="catalog-manager"><div class="catalog-tabs">${tabs}</div>${panel}</div>`;document.querySelectorAll('[data-cat-tab]').forEach(b=>b.onclick=()=>{catalogTab=b.dataset.catTab;renderCatalogs()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>catalogForm(b.dataset.add));document.querySelectorAll('[data-cat-edit]').forEach(b=>{b.onclick=()=>{const d=defs.find(x=>x.type===b.dataset.catEdit),item=d.rows.find(x=>String(x[d.id])===String(b.dataset.id));catalogForm(d.type,item)}});document.querySelectorAll('[data-cat-del]').forEach(b=>b.onclick=()=>deleteCatalog(b.dataset.catDel,b.dataset.id));if($('addPersonalCard'))$('addPersonalCard').onclick=()=>cardForm('PESSOAL');if($('addCompanyCard'))$('addCompanyCard').onclick=()=>cardForm('EMPRESA');document.querySelectorAll('[data-card-edit]').forEach(b=>b.onclick=()=>{const c=by(cards,b.dataset.cardEdit,'card_id');cardForm(c.card_type,c)});document.querySelectorAll('[data-card-del]').forEach(b=>b.onclick=()=>deleteCard(b.dataset.cardDel))}
async function refreshAdminData(){const boot=await api('/bootstrap'),eligible=await scheduleApi('/eligible-users');B=boot;B.users=eligible.users||[];if(!B.users.some(u=>String(u.id)===String(B.user.id)))B.users.unshift({id:B.user.id,email:B.user.email,name:B.user.name,profile:B.user.profile,entity_key:null});await reload();renderCatalogs()}
function cardForm(type,item=null){$('modalTitle').textContent=item?'Editar cartão':type==='EMPRESA'?'Novo cartão da empresa':'Novo cartão pessoal';$('modalBody').innerHTML=`<div class="form">${type==='EMPRESA'?`<div class="field"><label>Empresa *</label><select id="cardCompany">${opts(B.companies,'key','name')}</select></div>`:''}<div class="field"><label>Apelido *</label><input id="cardNick" placeholder="Ex.: Itaú Black" value="${esc(item?.nickname||'')}"></div><div class="field"><label>Número ou 4 finais *</label><input id="cardNumber" inputmode="numeric" autocomplete="off" placeholder="Número do cartão ou últimos 4 dígitos" value="${esc(item?.last4||'')}"><small>O sistema guarda somente os últimos 4 dígitos.</small></div><div class="field"><label>Bandeira</label><input id="cardBrand" placeholder="Visa, Mastercard…" value="${esc(item?.brand||'')}"></div><div class="field"><label>Banco / emissor</label><input id="cardIssuer" placeholder="Itaú, Bradesco…" value="${esc(item?.issuer||'')}"></div></div>`;$('modalActions').innerHTML='<button class="btn" id="modalClose">Cancelar</button><button class="btn primary" id="saveCard">Salvar</button>';showModal();if($('cardCompany')){$('cardCompany').value=item?.company_key||currentCompany()||B.companies[0]?.key||'';if(item)$('cardCompany').disabled=true}$('modalClose').onclick=hideModal;$('saveCard').onclick=async()=>{await cardApi('/cards',{method:'POST',body:JSON.stringify({card_id:item?.card_id||null,card_type:type,company_key:$('cardCompany')?.value||item?.company_key||null,nickname:$('cardNick').value,last4:$('cardNumber').value,brand:$('cardBrand').value,issuer:$('cardIssuer').value})});hideModal();await reload();renderCatalogs();renderCardOptions();flash(item?'Cartão atualizado.':'Cartão cadastrado.')}}
async function deleteCard(id){if(!confirm('Excluir este cartão do cadastro? O histórico das despesas antigas será preservado.'))return;await cardApi('/cards?id='+encodeURIComponent(id),{method:'DELETE'});await reload();renderCatalogs();renderCardOptions();flash('Cartão excluído.')}
function catalogForm(type,item=null){const d=catalogDefs().find(x=>x.type===type),hasCode=['cost_center','project'].includes(type),hasDescription=type!=='payment_method';$('modalTitle').textContent=item?'Editar '+d.label.toLowerCase():'Novo cadastro';$('modalBody').innerHTML=`<div class="form"><div class="field"><label>Empresa *</label><select id="cCompany">${opts(B.companies,'key','name')}</select></div>${hasCode?`<div class="field"><label>Código</label><input id="cCode" value="${esc(item?.code||'')}"></div>`:''}<div class="field"><label>Nome *</label><input id="cName" value="${esc(item?.name||'')}"></div>${hasDescription?`<div class="field full"><label>Descrição</label><textarea id="cDescription">${esc(item?.description||'')}</textarea></div>`:''}</div>`;$('modalActions').innerHTML='<button class="btn" id="modalClose">Cancelar</button><button class="btn primary" id="saveCatalog">Salvar</button>';showModal();$('cCompany').value=item?.company_key||currentCompany()||B.companies[0]?.key||'';if(item)$('cCompany').disabled=true;$('modalClose').onclick=hideModal;$('saveCatalog').onclick=async()=>{const payload={company_key:$('cCompany').value,name:$('cName').value};if(item)payload[d.id]=item[d.id];if(hasCode)payload.code=$('cCode').value;if(hasDescription)payload.description=$('cDescription').value;await catalogApi('/'+type,{method:'POST',body:JSON.stringify(payload)});hideModal();await refreshAdminData();flash(item?'Cadastro atualizado.':'Cadastro criado.')}}
async function deleteCatalog(type,id){const d=catalogDefs().find(x=>x.type===type),item=d?.rows.find(x=>String(x[d.id])===String(id));if(!item||!confirm(`Excluir “${item.name}”? Ele deixará de aparecer nos novos lançamentos, mas o histórico será preservado.`))return;await catalogApi('/'+type+'?id='+encodeURIComponent(id),{method:'DELETE'});await refreshAdminData();flash('Cadastro excluído.')}
async function loadAudit'''
js,n=re.subn(pattern,lambda m: replacement,js,count=1,flags=re.S)
if n!=1: raise SystemExit(f'catalog block replacement={n}')

# Geolocation is clickable; address link updates while editing.
old_geo_bind="$('geoBtn').onclick=()=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>{geo={latitude:p.coords.latitude,longitude:p.coords.longitude};$('geoText').textContent=`${geo.latitude.toFixed(5)}, ${geo.longitude.toFixed(5)}`;$('geoText').classList.remove('hidden');persist()},e=>alert(e.message),{enableHighAccuracy:true,timeout:10000}):alert('Geolocalização não suportada');"
new_geo_bind="$('geoBtn').onclick=()=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>{geo={latitude:p.coords.latitude,longitude:p.coords.longitude};renderGeoLink();persist()},e=>alert(e.message),{enableHighAccuracy:true,timeout:10000}):alert('Geolocalização não suportada');"
if old_geo_bind not in js: raise SystemExit('geo binding not found')
